<?php
require_once 'includes/functions.php'; require_login(); if(!is_admin()){http_response_code(403);exit('Akses ditolak');} page_title('Pengguna');$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$role=$_POST['role']??'customer';
 if($name && filter_var($email,FILTER_VALIDATE_EMAIL) && strlen($pass)>=8 && in_array($role,['super_admin','admin_unit','keuangan','operasional','customer'],true)){
  try{$hash=password_hash($pass,PASSWORD_DEFAULT);$pdo->prepare("INSERT INTO users(name,email,password,role,phone) VALUES(?,?,?,?,?)")->execute([$name,$email,$hash,$role,trim($_POST['phone']??'')]);flash('Pengguna berhasil dibuat.');header('Location: users.php');exit;}catch(PDOException $e){$error='Email sudah digunakan atau data tidak valid.';}
 }else $error='Isi semua data. Password minimal 8 karakter.';
}
$rows=$pdo->query("SELECT id,name,email,role,phone,is_active,created_at FROM users ORDER BY id DESC")->fetchAll();include 'includes/header.php'; ?>
<div class="page-head"><div><h1>Pengguna & Hak Akses</h1><p class="sub">Buat akun admin, operasional, keuangan, dan pelanggan.</p></div></div>
<div class="grid two-col"><div class="card"><h2 class="section-title">Tambah Pengguna</h2><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><?=csrf_field()?><div class="field"><label>Nama</label><input name="name" required></div><div class="field" style="margin-top:12px"><label>Email</label><input type="email" name="email" required></div><div class="field" style="margin-top:12px"><label>Password (min. 8 karakter)</label><input type="password" name="password" minlength="8" required></div><div class="field" style="margin-top:12px"><label>Role</label><select name="role"><option value="customer">Pelanggan</option><option value="admin_unit">Admin Unit</option><option value="operasional">Operasional</option><option value="keuangan">Keuangan</option><option value="super_admin">Super Admin</option></select></div><div class="field" style="margin-top:12px"><label>Telepon</label><input name="phone"></div><button class="btn" style="margin-top:16px">Buat Akun</button></form></div>
<div class="card"><h2 class="section-title">Daftar Pengguna</h2><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Email</th><th>Role</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e(str_replace('_',' ',$r['role']))?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
